@* Step indicator bar showing progress through the application steps *@

<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var status = GetStepStatus(stepIndex);
        <button class="step @status"
                disabled="@(status == "future")"
                @onclick="() => OnStepClicked(stepIndex)"
                aria-current="@(status == "current" ? "step" : null)">
            <span class="step-number">
                @if (status == "completed")
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>
        @if (stepIndex < StepNames.Length - 1)
        {
            <span class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<int> OnNavigate { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "current";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private async Task OnStepClicked(int step)
    {
        if (step < CurrentStep)
        {
            await OnNavigate.InvokeAsync(step);
        }
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    margin-bottom: 2rem;
    flex-wrap: wrap;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem 1rem;
    min-width: 100px;
    transition: opacity 0.2s;
}

.step:disabled {
    cursor: default;
}

.step-number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    font-weight: 600;
    font-size: 0.875rem;
    border: 2px solid #cbd5e1;
    background: white;
    color: #94a3b8;
    transition: all 0.2s;
}

.step.current .step-number {
    border-color: #3b82f6;
    background: #3b82f6;
    color: white;
}

.step.completed .step-number {
    border-color: #22c55e;
    background: #22c55e;
    color: white;
}

.step.future .step-number {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    color: #64748b;
    text-align: center;
    white-space: nowrap;
}

.step.current .step-label {
    color: #3b82f6;
    font-weight: 600;
}

.step.completed .step-label {
    color: #22c55e;
}

.step.future .step-label {
    opacity: 0.5;
}

.checkmark {
    font-size: 1rem;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #cbd5e1;
    margin-bottom: 1.25rem;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #22c55e;
}

@using sv_750522e258184baca58bbad5ebe246dc.Models

<div class="work-entry-editor">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Entry.Company"
                   @onchange="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title"
                   @onchange="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="form-group">
            <label class="checkbox-label">
                <input type="checkbox" checked="@_isCurrent"
                       @onchange="OnCurrentChanged" />
                Currently working here
            </label>
            @if (!_isCurrent)
            {
                <label>End Date</label>
                <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                       @onchange="e => Update(Entry with { EndDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
            }
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
    </div>
</div>

@code {
    private bool _isCurrent;

    [Parameter, EditorRequired]
    public WorkEntry Entry { get; set; } = default!;

    [Parameter]
    public int Index { get; set; }

    [Parameter]
    public bool CanRemove { get; set; }

    [Parameter]
    public EventCallback<WorkEntry> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnRemove { get; set; }

    protected override void OnParametersSet()
    {
        _isCurrent = Entry.EndDate is null && Entry.Company != "";
    }

    private void OnCurrentChanged(ChangeEventArgs e)
    {
        _isCurrent = (bool)(e.Value ?? false);
        if (_isCurrent)
        {
            Update(Entry with { EndDate = null });
        }
        else
        {
            Update(Entry with { EndDate = DateTime.Today });
        }
    }

    private void Update(WorkEntry updated)
    {
        OnChanged.InvokeAsync(updated);
    }
}

