+        await Task.Delay(1000);
+        return Interlocked.Increment(ref _nextId);
+    }
+
+    public async Task<bool> ValidateEmailAsync(string email)
+    {
+        await Task.Delay(300);
+        return !string.IsNullOrWhiteSpace(email)
+            && email.Contains('@')
+            && email.Contains('.');
+    }
+}
+

toolArgs.file_text:
@* Step indicator bar showing progress through the application steps *@

<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var status = GetStepStatus(stepIndex);
        <button class="step @status"
                disabled="@(status == "future")"
                @onclick="() => OnStepClicked(stepIndex)"
                aria-current="@(status == "current" ? "step" : null)">
            <span class="step-number">
                @if (status == "completed")
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>
        @if (stepIndex < StepNames.Length - 1)
        {
            <span class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<int> OnNavigate { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "current";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private async Task OnStepClicked(int step)
    {
        if (step < CurrentStep)
        {
            await OnNavigate.InvokeAsync(step);
        }
    }
}

