toolArgs.file_text:
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    margin-bottom: 2rem;
    flex-wrap: wrap;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem 1rem;
    min-width: 100px;
    transition: opacity 0.2s;
}

.step:disabled {
    cursor: default;
}

.step-number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    font-weight: 600;
    font-size: 0.875rem;
    border: 2px solid #cbd5e1;
    background: white;
    color: #94a3b8;
    transition: all 0.2s;
}

.step.current .step-number {
    border-color: #3b82f6;
    background: #3b82f6;
    color: white;
}

.step.completed .step-number {
    border-color: #22c55e;
    background: #22c55e;
    color: white;
}

.step.future .step-number {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    color: #64748b;
    text-align: center;
    white-space: nowrap;
}

.step.current .step-label {
    color: #3b82f6;
    font-weight: 600;
}

.step.completed .step-label {
    color: #22c55e;
}

.step.future .step-label {
    opacity: 0.5;
}

.checkmark {
    font-size: 1rem;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #cbd5e1;
    margin-bottom: 1.25rem;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #22c55e;
}

