@using sv_750522e258184baca58bbad5ebe246dc.Models

<section class="step-section">
    @if (_submitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been successfully submitted.</p>
            <p class="application-id">Application ID: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        <h2>Review & Submit</h2>
        <p class="step-description">Please review your application before submitting.</p>

        @if (_error is not null)
        {
            <div class="validation-error">@_error</div>
        }

        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="review-grid">
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-card">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <div class="review-dates">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-card">
                    <strong>@r.Name</strong> — @r.Relationship
                    <div>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</div>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <div class="review-cover-letter">@CoverLetter</div>
        </div>

        <div class="step-actions">
            <button class="btn-outline" @onclick="OnBack">Back</button>
            <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @(_isSubmitting ? "Submitting…" : "Submit Application")
            </button>
        </div>
    }
</section>

@code {
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _error;

    [Parameter, EditorRequired]
    public PersonalInfo Personal { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<WorkEntry> WorkEntries { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<Reference> References { get; set; } = default!;

    [Parameter]
    public string CoverLetter { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<int> OnEditSection { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<int> OnSubmitted { get; set; }

    [Parameter, EditorRequired]
    public Func<Task<int>> SubmitFunc { get; set; } = default!;

    private async Task HandleSubmit()
    {
        _isSubmitting = true;
        _error = null;
        try
        {
            _applicationId = await SubmitFunc();
            _submitted = true;
            await OnSubmitted.InvokeAsync(_applicationId);
        }
        catch (Exception ex)
        {
            _error = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

