@using sv_750522e258184baca58bbad5ebe246dc.Models

<section class="step-section">
    <h2>References</h2>
    <p class="step-description">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceEditor Ref="@References[index]"
                         Index="index"
                         CanRemove="@(References.Count > 2)"
                         OnChanged="e => HandleChanged(index, e)"
                         OnRemove="() => HandleRemove(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">
            + Add Reference
        </button>
    }

    @if (_validationError is not null)
    {
        <div class="validation-error">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    private string? _validationError;

    [Parameter, EditorRequired]
    public List<Reference> References { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<List<Reference>> OnChanged { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnNext { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    private void HandleChanged(int index, Reference updated)
    {
        var list = new List<Reference>(References);
        list[index] = updated;
        OnChanged.InvokeAsync(list);
    }

    private void HandleRemove(int index)
    {
        var list = new List<Reference>(References);
        list.RemoveAt(index);
        OnChanged.InvokeAsync(list);
    }

    private void AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<Reference>(References) { new("", "", "", "") };
        OnChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        if (References.Count < 2)
        {
            _validationError = "Please provide at least 2 references.";
            return;
        }
        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) ||
                                 string.IsNullOrWhiteSpace(r.Relationship) ||
                                 string.IsNullOrWhiteSpace(r.Email)))
        {
            _validationError = "Each reference must have a name, relationship, and email.";
            return;
        }
        _validationError = null;
        await OnNext.InvokeAsync();
    }
}

