@page "/apply"
@using sv_750522e258184baca58bbad5ebe246dc.Models
@rendermode InteractiveServer

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep" OnNavigate="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Personal="_personal"
                              EmailError="@_emailError"
                              OnChanged="HandlePersonalChanged"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnChanged="e => _workEntries = e"
                             OnNext="() => GoToStep(2)"
                             OnBack="() => GoToStep(0)" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnChanged="e => _references = e"
                            OnNext="() => GoToStep(3)"
                            OnBack="() => GoToStep(1)" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnChanged="e => _coverLetter = e"
                             OnNext="() => GoToStep(4)"
                             OnBack="() => GoToStep(2)" />
            break;
        case 4:
            <ReviewStep Personal="_personal"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        OnEditSection="GoToStep"
                        OnBack="() => GoToStep(3)"
                        OnSubmitted="id => { }"
                        SubmitFunc="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private PersonalInfo _personal = new("", "", "", "");
    private List<WorkEntry> _workEntries = [new("", "", DateTime.Today, DateTime.Today, "")];
    private List<Reference> _references = [new("", "", "", ""), new("", "", "", "")];
    private string _coverLetter = "";
    private string? _emailError;

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void HandlePersonalChanged(PersonalInfo updated)
    {
        _personal = updated;
        _emailError = null;
    }

    private async Task HandlePersonalNext()
    {
        _emailError = null;
        var isValid = await ApplicationService.ValidateEmailAsync(_personal.Email);
        if (!isValid)
        {
            _emailError = "Please enter a valid email address.";
            return;
        }
        GoToStep(1);
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            _personal,
            new WorkHistory(_workEntries),
            _references,
            _coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-container {
    max-width: 720px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-container h1 {
    text-align: center;
    color: #1e293b;
    margin-bottom: 2rem;
}

/* Shared form styles */
::deep .step-section h2 {
    color: #1e293b;
    margin-bottom: 1.5rem;
    font-size: 1.25rem;
}

::deep .step-description {
    color: #64748b;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label {
    display: block;
    font-weight: 600;
    font-size: 0.875rem;
    color: #334155;
    margin-bottom: 0.25rem;
}

::deep .form-group input,
::deep .form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

::deep .form-group input:focus,
::deep .form-group textarea:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

::deep .input-error {
    border-color: #ef4444 !important;
}

::deep .field-error {
    color: #ef4444;
    font-size: 0.8125rem;
    margin-top: 0.25rem;
    display: block;
}

::deep .form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

::deep .validation-error {
    background: #fef2f2;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    border: 1px solid #fecaca;
    font-size: 0.875rem;
    margin: 1rem 0;
}

::deep .step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e2e8f0;
}

::deep .btn-primary {
    background: #3b82f6;
    color: white;
    border: none;
    padding: 0.625rem 1.5rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

::deep .btn-primary:hover:not(:disabled) {
    background: #2563eb;
}

::deep .btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-outline {
    background: white;
    color: #475569;
    border: 1px solid #cbd5e1;
    padding: 0.625rem 1.5rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

::deep .btn-outline:hover {
    background: #f1f5f9;
    border-color: #94a3b8;
}

::deep .btn-secondary {
    background: white;
    color: #3b82f6;
    border: 1px dashed #93c5fd;
    padding: 0.5rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    cursor: pointer;
    width: 100%;
    transition: all 0.2s;
}

::deep .btn-secondary:hover {
    background: #eff6ff;
    border-color: #3b82f6;
}

