+    color: #1e293b;
+    margin-bottom: 1.5rem;
+    font-size: 1.25rem;
+}
+
+::deep .step-description {
+    color: #64748b;
+    margin-bottom: 1rem;
+    font-size: 0.875rem;
+}
+
+::deep .form-group {
+    margin-bottom: 1rem;
+}
+
+::deep .form-group label {
+    display: block;
+    font-weight: 600;
+    font-size: 0.875rem;
+    color: #334155;
+    margin-bottom: 0.25rem;
+}
+
+::deep .form-group input,
+::deep .form-group textarea {
+    width: 100%;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #cbd5e1;
+    border-radius: 0.375rem;
+    font-size: 0.875rem;
+    transition: border-color 0.2s;
+    box-sizing: border-box;
+}
+
+::deep .form-group input:focus,
+::deep .form-group textarea:focus {
+    outline: none;
+    border-color: #3b82f6;
+    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
+}
+
+::deep .input-error {
+    border-color: #ef4444 !important;
+}
+
+::deep .field-error {
+    color: #ef4444;
+    font-size: 0.8125rem;
+    margin-top: 0.25rem;
+    display: block;
+}
+
+::deep .form-row {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 1rem;
+}
+
+::deep .validation-error {
+    background: #fef2f2;
+    color: #dc2626;
+    padding: 0.75rem 1rem;
+    border-radius: 0.375rem;
+    border: 1px solid #fecaca;
+    font-size: 0.875rem;
+    margin: 1rem 0;
+}
+
+::deep .step-actions {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 2rem;
+    padding-top: 1.5rem;
+    border-top: 1px solid #e2e8f0;
+}
+
+::deep .btn-primary {
+    background: #3b82f6;
+    color: white;
+    border: none;
+    padding: 0.625rem 1.5rem;
+    border-radius: 0.375rem;
+    font-size: 0.875rem;
+    font-weight: 600;
+    cursor: pointer;
+    transition: background 0.2s;
+}
+
+::deep .btn-primary:hover:not(:disabled) {
+    background: #2563eb;
+}
+
+::deep .btn-primary:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+::deep .btn-outline {
+    background: white;
+    color: #475569;
+    border: 1px solid #cbd5e1;
+    padding: 0.625rem 1.5rem;
+    border-radius: 0.375rem;
+    font-size: 0.875rem;
+    font-weight: 600;
+    cursor: pointer;
+    transition: all 0.2s;
+}
+
+::deep .btn-outline:hover {
+    background: #f1f5f9;
+    border-color: #94a3b8;
+}
+
+::deep .btn-secondary {
+    background: white;
+    color: #3b82f6;
+    border: 1px dashed #93c5fd;
+    padding: 0.5rem 1rem;
+    border-radius: 0.375rem;
+    font-size: 0.875rem;
+    cursor: pointer;
+    width: 100%;
+    transition: all 0.2s;
+}
+
+::deep .btn-secondary:hover {
+    background: #eff6ff;
+    border-color: #3b82f6;
+}
